package ai.interviewiq.api.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="candidate_answers") public class CandidateAnswer extends BaseEntity { @OneToOne @JoinColumn(nullable=false,unique=true) private InterviewQuestion interviewQuestion; @Column(nullable=false,columnDefinition="TEXT") private String answerText; @Column(nullable=false) private String inputMethod; @Column(nullable=false) private Instant submittedAt; protected CandidateAnswer(){} public CandidateAnswer(String text,String method){answerText=text;inputMethod=method;submittedAt=Instant.now();} void setInterviewQuestion(InterviewQuestion q){interviewQuestion=q;} public String getAnswerText(){return answerText;} public String getInputMethod(){return inputMethod;} public Instant getSubmittedAt(){return submittedAt;} public void replace(String text,String method){answerText=text;inputMethod=method;submittedAt=Instant.now();} }
